from io import BytesIO
from mutagen.mp4 import MP4
from copy import copy, deepcopy
import os
from src.lib.entities.metadata import ExchangeMetaInfo, FileMetaInfo
from pathlib import Path


class AudioProcessorBase:
    _audio_object: MP4

    @property
    def info(self) -> ExchangeMetaInfo:
        """
        immutable object
        should be exchange meta info
        """
        data = copy(dict(self._audio_object))
        einfo = FileMetaInfo(**data).to_exchange_meta_info()

        if einfo.duration is None:
            einfo.duration = self._audio_object.info.length
        if einfo.bit_rate is None:
            einfo.bit_rate = self._audio_object.info.bitrate/1000
        if einfo.sample_rate is None:
            einfo.sample_rate = self._audio_object.info.sample_rate
        return einfo


class AudioFileProcessor(AudioProcessorBase):
    _file_path: str | None

    def __init__(self, file_path: str) -> None:
        if file_path is not None:
            if not os.path.isabs(file_path):
                raise FileNotFoundError("song path must be abs path")
            if not os.path.exists(file_path):
                raise FileNotFoundError("song must exists")
            self._file_path = file_path
            self._file_io = None
            self._audio_object = MP4(file_path)

    def _modify_name(self):
        if self._file_path is None:
            raise ValueError("can not rename a BytesIO object")
        info = self.info
        new_name = os.path.basename(info.generate_audio_file_path())
        old_name = os.path.basename(self._file_path)
        if new_name == old_name:
            return
        p = Path(self._file_path)
        new_p = p.with_name(new_name)
        if not p.exists():
            raise FileNotFoundError(p)
        if new_p.exists():
            raise FileExistsError(new_p)
        p.rename(new_p)
        self._file_path = str(new_p)

    def update_meta_info(self, info: FileMetaInfo):
        new_info = info.model_dump()
        # todo some itunes tag can not write into the tags
        for key, value in new_info.items():
            try:
                self._audio_object[key] = value
            except Exception as e:
                print(key+str(e))

    def is_meta_info_changed(self, info: FileMetaInfo) -> bool:
        for key in FileMetaInfo.model_fields:
            new_value = info.__dict__.get(key)
            file_value = self.info.__dict__.get(key)
            if new_value is None:
                continue
            if new_value != file_value:
                return True
        return False

    def save(self):
        self._audio_object.save()

    def delete(self):
        if self.info.file_path:
            os.remove(self.info.file_path)


class AudioStreamProcessor(AudioProcessorBase):
    _file_path: str | None
    _file_io: BytesIO | None

    def __init__(self, file_io: BytesIO) -> None:
        self._file_io = file_io
        self._audio_object = MP4(file_io)


